da bajariladi; qoldiqlarni teskari o‘qib 110110₍4₎ olinadi. Qoldiqlar (bajarilish tartibida): 0, 1, 1, 0, 1, 1.","cognitive":"qollash","difficulty":4,"steps":["81 ÷ 4 = 20, qoldiq 1","1300 ÷ 4 = 325, qoldiq 0","20 ÷ 4 = 5, qoldiq 0","325 ÷ 4 = 81, qoldiq 1","1 ÷ 4 = 0, qoldiq 1","5 ÷ 4 = 1, qoldiq 1"],"sequence":[1,3,0,2,5,4]},{"ref":"m05-20261018:y2y3:066","lesson":2,"format":"Y3","stem":"1573₍10₎ sonini 5 lik sanoq tizimiga o‘tkazishda qoldiqli bo‘lish qadamlarini bajarilish tartibida joylang.","source":"ICT7 (2021), PDF 13–16; 2026 spetsifikatsiyasi Y3, S3.NUM.02; original misol","group":"qoldiqli-bolish","explanation":"Bo‘lish zanjiri shu tartibda bajariladi; qoldiqlarni teskari o‘qib 22243₍5₎ olinadi. Qoldiqlar (bajarilish tartibida): 3, 4, 2, 2, 2.","cognitive":"qollash","difficulty":4,"steps":["62 ÷ 5 = 12, qoldiq 2","1573 ÷ 5 = 314, qoldiq 3","12 ÷ 5 = 2, qoldiq 2","314 ÷ 5 = 62, qoldiq 4","2 ÷ 5 = 0, qoldiq 2"],"sequence":[1,3,0,2,4]},{"ref":"m05-20261018:y2y3:067","lesson":2,"format":"Y3","stem":"1849₍10₎ sonini 6 lik sanoq tizimiga o‘tkazishda qoldiqli bo‘lish qadamlarini bajarilish tartibida joylang.","source":"ICT7 (2021), PDF 13–16; 2026 spetsifikatsiyasi Y3, S3.NUM.02; original misol","group":"qoldiqli-bolish","explanation":"Bo‘lish zanjiri shu tartibda bajariladi; qoldiqlarni teskari o‘qib 12321₍6₎ olinadi. Qoldiqlar (bajarilish tartibida): 1, 2, 3, 2, 1.","cognitive":"qollash","difficulty":4,"steps":["51 ÷ 6 = 8, qoldiq 3","1849 ÷ 6 = 308, qoldiq 1","8 ÷ 6 = 1, qoldiq 2","308 ÷ 6 = 51, qoldiq 2","1 ÷ 6 = 0, qoldiq 1"],"sequence":[1,3,0,2,4]},{"ref":"m05-20261018:y2y3:068","lesson":2,"format":"Y3","stem":"2201₍10₎ sonini 7 lik sanoq tizimiga o‘tkazishda qoldiqli bo‘lish qadamlarini bajarilish tartibida joylang.","source":"ICT7 (2021), PDF 13–16; 2026 spetsifikatsiyasi Y3, S3.NUM.02; original misol","group":"qoldiqli-bolish","explanation":"Bo‘lish zanjiri shu tartibda bajariladi; qoldiqlarni teskari o‘qib 6263₍7₎ olinadi. Qoldiqlar (bajarilish tartibida): 3, 6, 2, 6.","cognitive":"qollash","difficulty":4,"steps":["44 ÷ 7 = 6, qoldiq 2","2201 ÷ 7 = 314, qoldiq 3","6 ÷ 7 = 0, qoldiq 6","314 ÷ 7 = 44, qoldiq 6"],"sequence":[1,3,0,2]},{"ref":"m05-20261018:y2y3:069","lesson":2,"format":"Y3","stem":"2843₍10₎ sonini 8 lik sanoq tizimiga o‘tkazishda qoldiqli bo‘lish qadamlarini bajarilish tartibida joylang.","source":"ICT7 (2021), PDF 13–16; 2026 spetsifikatsiyasi Y3, S3.NUM.02; original misol","group":"qoldiqli-bolish","explanation":"Bo‘lish zanjiri shu tartibda bajariladi; qoldiqlarni teskari o‘qib 5433₍8₎ olinadi. Qoldiqlar (bajarilish tartibida): 3, 3, 4, 5.","cognitive":"qollash","difficulty":4,"steps":["44 ÷ 8 = 5, qoldiq 4","2843 ÷ 8 = 355, qoldiq 3","5 ÷ 8 = 0, qoldiq 5","355 ÷ 8 = 44, qoldiq 3"],"sequence":[1,3,0,2]},{"ref":"m05-20261018:y2y3:070","lesson":2,"format":"Y3","stem":"3127₍10₎ sonini 9 lik sanoq tizimiga o‘tkazishda qoldiqli bo‘lish qadamlarini bajarilish tartibida joylang.","source":"ICT7 (2021), PDF 13–16; 2026 spetsifikatsiyasi Y3, S3.NUM.02; original misol","group":"qoldiqli-bolish","explanation":"Bo‘lish zanjiri shu tartibda bajariladi; qoldiqlarni teskari o‘qib 4254₍9₎ olinadi. Qoldiqlar (bajarilish tartibida): 4, 5, 2, 4.","cognitive":"qollash","difficulty":4,"steps":["38 ÷ 9 = 4, qoldiq 2","3127 ÷ 9 = 347, qoldiq 4","4 ÷ 9 = 0, qoldiq 4","347 ÷ 9 = 38, qoldiq 5"],"sequence":[1,3,0,2]},{"ref":"m05-20261018:y2y3:071","lesson":1,"format":"Y3","stem":"23₍p₎ = 13₍10₎ tenglamada p asosini topish bosqichlarini mantiqiy tartiblang.","source":"ICT7 (2021), PDF 11–12; 2026 spetsifikatsiyasi Y3, S3.NUM.01; manbaga tayangan original","group":"noma-lum-asos-yechim","explanation":"Yoyiq yozuv 2p+3=13, demak p=(13−3)/2=5; asos barcha yozuv raqamlaridan katta.","cognitive":"qollash","difficulty":4,"steps":["O‘zgarmas hadni ajratish: 2·p = 10","Boshlang‘ich shartni yozish: 23₍p₎ = 13₍10₎","Asosni hisoblab, p > 3 shartini tekshirish: p = 5","Pozitsiyali yoyiq yozuv: 2·p + 3 = 13"],"sequence":[1,3,0,2]},{"ref":"m05-20261018:y2y3:072","lesson":1,"format":"Y3","stem":"32₍p₎ = 23₍10₎ tenglamada p asosini topish bosqichlarini mantiqiy tartiblang.","source":"ICT7 (2021), PDF 11–12; 2026 spetsifikatsiyasi Y3, S3.NUM.01; manbaga tayangan original","group":"noma-lum-asos-yechim","explanation":"Yoyiq yozuv 3p+2=23, demak p=(23−2)/3=7; asos barcha yozuv raqamlaridan katta.","cognitive":"qollash","difficulty":4,"steps":["O‘zgarmas hadni ajratish: 3·p = 21","Boshlang‘ich shartni yozish: 32₍p₎ = 23₍10₎","Asosni hisoblab, p > 3 shartini tekshirish: p = 7","Pozitsiyali yoyiq yozuv: 3·p + 2 = 23"],"sequence":[1,3,0,2]},{"ref":"m05-20261018:y2y3:073","lesson":1,"format":"Y3","stem":"24₍p₎ = 22₍10₎ tenglamada p asosini topish bosqichlarini mantiqiy tartiblang.","source":"ICT7 (2021), PDF 11–12; 2026 spetsifikatsiyasi Y3, S3.NUM.01; manbaga tayangan original","group":"noma-lum-asos-yechim","explanation":"Yoyiq yozuv 2p+4=22, demak p=(22−4)/2=9; asos barcha yozuv raqamlaridan katta.","cognitive":"qollash","difficulty":4,"steps":["O‘zgarmas hadni ajratish: 2·p = 18","Boshlang‘ich shartni yozish: 24₍p₎ = 22₍10₎","Asosni hisoblab, p > 4 shartini tekshirish: p = 9","Pozitsiyali yoyiq yozuv: 2·p + 4 = 22"],"sequence":[1,3,0,2]},{"ref":"m05-20261018:y2y3:074","lesson":1,"format":"Y3","stem":"43₍p₎ = 51₍10₎ tenglamada p asosini topish bosqichlarini mantiqiy tartiblang.","source":"ICT7 (2021), PDF 11–12; 2026 spetsifikatsiyasi Y3, S3.NUM.01; manbaga tayangan original","group":"noma-lum-asos-yechim","explanation":"Yoyiq yozuv 4p+3=51, demak p=(51−3)/4=12; asos barcha yozuv raqamlaridan katta.","cognitive":"qollash","difficulty":4,"steps":["O‘zgarmas hadni ajratish: 4·p = 48","Boshlang‘ich shartni yozish: 43₍p₎ = 51₍10₎","Asosni hisoblab, p > 4 shartini tekshirish: p = 12","Pozitsiyali yoyiq yozuv: 4·p + 3 = 51"],"sequence":[1,3,0,2]}]'::jsonb;
  q jsonb;
  q_ref text;
  lesson_row public.lessons%rowtype;
  example_row public.questions%rowtype;
  qid uuid;
  oid uuid;
  leftids uuid[];
  rightids uuid[];
  mapping jsonb;
  payload jsonb;
  fmt text;
  i int;
  j int;
  cnt int;
  yy2 int;
  yy3 int;
  already int;
BEGIN
 IF jsonb_array_length(items) <> 74 THEN RAISE EXCEPTION 'M05 item list must have 74';END IF;
 SELECT count(*) FILTER (WHERE q.format='Y2'),count(*) FILTER (WHERE q.format='Y3')
 INTO yy2,yy3
 FROM public.questions q JOIN public.lessons l ON l.id=q.source_lesson_id
 JOIN public.modules m ON m.id=l.module_id WHERE m.code='M05' AND q.status='published';
 SELECT count(*) INTO already FROM public.questions WHERE source_reference LIKE 'm05-20261018:y2y3:%';
 IF already=74 AND yy2=50 AND yy3=50 THEN
   RAISE NOTICE 'M05 source batch already inserted; no changes';
   RETURN;
 END IF;
 IF already <> 0 OR yy2<>6 OR yy3<>20 THEN
   RAISE EXCEPTION 'M05 prerequisites drift: existing batch %, Y2 %, Y3 %',already,yy2,yy3;
 END IF;
 FOR q IN SELECT value FROM jsonb_array_elements(items) LOOP
   q_ref:=q->>'ref'; fmt:=q->>'format';
   SELECT l.* INTO STRICT lesson_row FROM public.lessons l
   JOIN public.modules m ON m.id=l.module_id
   WHERE m.code='M05' AND l.order_idx=(q->>'lesson')::int AND l.status='published';
   SELECT ex.* INTO STRICT example_row FROM public.questions ex
   JOIN public.constructs c ON c.id=ex.construct_id
   WHERE ex.source_lesson_id=lesson_row.id AND ex.status='published'
   AND c.code='S3.NUM.0'||(q->>'lesson')
   LIMIT 1;
   INSERT INTO public.questions(subject_id,construct_id,group_code,format,cognitive,
      difficulty,stem_md,is_generated,status,source_reference,source_lesson_id)
   VALUES (example_row.subject_id,example_row.construct_id,example_row.group_code,
       fmt::public.question_format,(q->>'cognitive')::public.cognitive_level,
       (q->>'difficulty')::int,q->>'stem',false,'published'::public.content_status,
       q_ref,lesson_row.id)
   RETURNING id INTO qid;
   leftids:=ARRAY[]::uuid[];rightids:=ARRAY[]::uuid[];mapping:='{}'::jsonb;
   IF fmt='Y2' THEN
      IF jsonb_array_length(q->'left')<>4 OR jsonb_array_length(q->'right')<>4
        OR jsonb_array_length(q->'pairs')<>4 THEN
        RAISE EXCEPTION 'Y2 invalid options: %',q_ref;
      END IF;
      FOR i IN 0..3 LOOP
        INSERT INTO public.question_options(question_id,side,order_idx,content_md)
        VALUES (qid,'a',i+1,q->'left'->>i) RETURNING id INTO oid;
        leftids:=array_append(leftids,oid);
        INSERT INTO public.question_options(question_id,side,order_idx,content_md)
        VALUES (qid,'b',i+1,q->'right'->>i) RETURNING id INTO oid;
        rightids:=array_append(rightids,oid);
      END LOOP;
      FOR i IN 0..3 LOOP
         j:=(q->'pairs'->>i)::int+1;
         IF j<1 OR j>4 THEN RAISE EXCEPTION 'Y2 invalid match %',q_ref;END IF;
         mapping:=mapping||jsonb_build_object(leftids[i+1]::text,rightids[j]);
      END LOOP;
      payload:=jsonb_build_object('pairs',mapping);
   ELSIF fmt='Y3' THEN
      cnt:=jsonb_array_length(q->'steps');
      IF cnt<4 OR cnt>7 OR jsonb_array_length(q->'sequence')<>cnt
        THEN RAISE EXCEPTION 'Y3 invalid options %',q_ref;END IF;
      FOR i IN 0..cnt-1 LOOP
         INSERT INTO public.question_options(question_id,side,order_idx,content_md)
         VALUES(qid,'a',i+1,q->'steps'->>i) RETURNING id INTO oid;
         leftids:=array_append(leftids,oid);
      END LOOP;
      mapping:='[]'::jsonb;
      FOR i IN 0..cnt-1 LOOP
         j:=(q->'sequence'->>i)::int+1;
         IF j<1 OR j>cnt THEN RAISE EXCEPTION 'Y3 invalid position %',q_ref; END IF;
         mapping:=mapping||jsonb_build_array(leftids[j]);
      END LOOP;
      payload:=jsonb_build_object('order',mapping);
   ELSE RAISE EXCEPTION 'Unexpected M05 format %',fmt;END IF;
   INSERT INTO public.question_keys(question_id,payload,explanation_md)
   VALUES(qid,payload,q->>'explanation');
 END LOOP;
 SELECT count(*) FILTER(WHERE q.format='Y2'),count(*) FILTER(WHERE q.format='Y3')
 INTO yy2, yy3 FROM public.questions q JOIN public.lessons l ON l.id=q.source_lesson_id
 JOIN public.modules m ON m.id=l.module_id WHERE m.code='M05' AND q.status='published';
 IF yy2<>50 OR yy3<>50 THEN RAISE EXCEPTION 'M05 postcondition: Y2 %,Y3 %',yy2,yy3;END IF;
 IF (SELECT COUNT(*) FROM public.questions WHERE source_reference LIKE 'm05-20261018:y2y3:%')<>74
 THEN RAISE EXCEPTION 'M05 batch incomplete'; END IF;
END $m05$;
COMMIT;
SELECT q.format::text as format,count(*) n FROM public.questions q
 JOIN public.lessons l ON l.id=q.source_lesson_id
 JOIN public.modules m ON m.id=l.module_id
 WHERE m.code='M05' AND q.status='published' GROUP BY q.format ORDER BY q.format;
